import { ArrowLeft,ArrowUpRight,Bell,BookOpen,BriefcaseBusiness,Check,ChevronRight,CircleAlert,Database,FileSearch,Filter,Flame,LayoutGrid,List,Menu,Radar,Search,ShieldCheck,Sparkles,Target,TrendingDown,TrendingUp,X } from "lucide-react";
import { AnimatePresence,motion } from "motion/react";
import { useCallback,useEffect,useMemo,useState,type ReactNode } from "react";
import { Link,NavLink,Navigate,Route,Routes,useNavigate,useParams,useSearchParams } from "react-router-dom";
import { TrendChart } from "./components/TrendChart";
import { radarRepository } from "./data/RadarRepository";
import type { Evidence,Problem,Signal,SourceType,TrendState } from "./mockData";

const stateLabel:Record<TrendState,string>={new:"新出现",rising:"升温",steady:"持续",falling:"降温",archived:"归档"};
const confidenceLabel={high:"高置信",medium:"中置信",low:"待观察"};
const evidenceLabel={verified:"内容已验证",lead_only:"仅作线索",failed:"访问失败"};

function useLoad<T>(loader:()=>Promise<T>,deps:unknown[]){const [data,setData]=useState<T>();const [error,setError]=useState(false);const [loading,setLoading]=useState(true);useEffect(()=>{let live=true;setLoading(true);setError(false);loader().then(value=>{if(live)setData(value)}).catch(()=>{if(live)setError(true)}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},deps);return{data,error,loading};}
function formatDate(date:string){return new Intl.DateTimeFormat("zh-CN",{month:"short",day:"numeric"}).format(new Date(date));}

function Shell({children}:{children:ReactNode}){
  const [menuOpen,setMenuOpen]=useState(false);
  const links=[["/","总览"],["/problems","动态难题"],["/signals","求职快讯"],["/evidence","证据库"],["/method","数据方法"]];
  const scenario=new URLSearchParams(location.search).get("scenario");
  return <div className="app-shell"><header className="topbar"><Link className="brand" to="/"><span className="brand-mark"><Radar size={17}/></span><span>研究雷达</span></Link><nav className={menuOpen?"nav open":"nav"} aria-label="主导航">{links.map(([to,label])=><NavLink key={to} to={to} end={to==="/"} onClick={()=>setMenuOpen(false)}>{label}</NavLink>)}</nav><div className="top-actions"><span className="demo-badge"><i/>演示数据</span><Link className="icon-button" to="/evidence" aria-label="搜索证据"><Search size={17}/></Link><button className="icon-button mobile-menu" aria-label="打开导航" onClick={()=>setMenuOpen(!menuOpen)}>{menuOpen?<X size={18}/>:<Menu size={18}/>}</button></div></header>{scenario==="stale"&&<div className="scenario-notice"><CircleAlert/>当前展示上一批可用数据，最近一次更新尚未完成。</div>}{scenario==="partial"&&<div className="scenario-notice"><CircleAlert/>部分来源暂不可用，页面仅展示已成功载入的样本。</div>}<main>{children}</main><footer><span>RADAR / MVP 0.1</span><span><Database size={14}/>当前为产品逻辑演示，所有数据均为模拟样本</span><button><Bell size={14}/>周报订阅即将开放</button></footer></div>;
}

function LoadingBlock(){return <div className="loading-block" aria-label="正在加载"><span/><span/><span/></div>}
function ErrorBlock(){return <div className="empty-state"><CircleAlert/><h2>这一组数据暂时没有加载成功</h2><p>刷新页面即可重新读取演示数据。</p><button onClick={()=>location.reload()}>重新加载</button></div>}

function Sparkline({problem}:{problem:Problem}){const points=problem.history.map((v,i)=>`${(i/(problem.history.length-1))*100},${34-((v-10)/85)*30}`).join(" ");const last=points.split(" ").at(-1)?.split(",")[1];return <svg className="sparkline" viewBox="0 0 100 38" preserveAspectRatio="none" aria-hidden="true"><polyline points={points} fill="none" stroke={problem.color} strokeWidth="2" vectorEffect="non-scaling-stroke"/><circle cx="100" cy={last} r="2.3" fill={problem.color}/></svg>}
function TrendBadge({problem}:{problem:Problem}){return <span className={`trend-pill ${problem.state}`}>{problem.state==="falling"?<TrendingDown size={11}/>:problem.state==="rising"?<TrendingUp size={11}/>:problem.state==="new"?<Flame size={11}/>:null}{stateLabel[problem.state]} {problem.delta>0?`+${problem.delta}`:problem.delta}</span>}

function ProblemRow({problem}:{problem:Problem}){return <motion.article className="problem-card" layout initial={{opacity:0,y:8}} animate={{opacity:1,y:0}}><div className="problem-index">{problem.index}</div><div className="problem-main"><div className="problem-title-row"><h2>{problem.name}</h2><TrendBadge problem={problem}/></div><p>{problem.definition}</p><div className="problem-meta"><span>{problem.evidence} 条有效证据</span><span>{problem.publishers} 个发布方</span><span>{problem.signal}</span></div></div><div className="problem-score"><Sparkline problem={problem}/><div><strong>{problem.score}</strong><span>/100</span></div></div><Link className="card-link" to={`/problems/${problem.id}`} aria-label={`查看${problem.name}`}><ArrowUpRight size={17}/></Link></motion.article>}

function ScanVisual(){return <div className="scan-visual" aria-hidden="true"><div className="scan-ring ring-one"/><div className="scan-ring ring-two"/><div className="scan-ring ring-three"/><div className="scan-line"/><span className="signal-dot dot-a"/><span className="signal-dot dot-b"/><span className="signal-dot dot-c"/><Radar size={25}/></div>}

function HomePage(){const o=useLoad(()=>radarRepository.getOverview(),[]);const p=useLoad(()=>radarRepository.getProblems(),[]);const s=useLoad(()=>radarRepository.getSignals(),[]);if(o.error||p.error||s.error)return <ErrorBlock/>;if(o.loading||p.loading||s.loading||!o.data||!p.data||!s.data)return <LoadingBlock/>;if(!p.data.length)return <div className="page-wrap"><PageIntro eyebrow="MARKET SIGNALS" title="本周暂未形成可信难题" description="当前观察窗口内没有达到展示阈值的问题。新的有效证据进入后，这里会自动更新。"/><div className="empty-state"><FileSearch/><h2>等待更多可验证信号</h2><p>你仍可以前往数据方法页查看问题如何被发现和评分。</p><Link to="/method">查看数据方法</Link></div></div>;const top=p.data.slice(0,3);return <motion.div initial={{opacity:0}} animate={{opacity:1}}><section className="workspace"><div className="workspace-head"><div><p className="overline">WEEK 37 · MARKET SIGNALS</p><h1>本周值得关注的<br/>大模型难题</h1></div><div className="update-meta"><span>最近更新</span><strong>今天 09:40</strong><small>{o.data.verifiedCount} 条有效证据 · {o.data.publisherCount} 个发布方</small></div></div><div className="signal-layout"><div className="problem-stack">{top.map(problem=><ProblemRow key={problem.id} problem={problem}/>)}<Link className="all-problems" to="/problems">查看全部动态问题 <span>{o.data.problemCount}</span><ArrowUpRight size={17}/></Link></div><aside className="insight-panel"><ScanVisual/><p className="overline">WEEKLY JUDGEMENT</p><h2>{o.data.judgement}</h2><p>{o.data.judgementDetail}</p><div className="insight-evidence"><BookOpen size={16}/><span>由 3 类来源交叉支持</span><strong>高置信</strong></div><Link className="primary-action" to={`/problems/${top[0].id}`}>查看判断依据 <ArrowUpRight size={16}/></Link></aside></div></section><section className="dashboard-grid"><div className="chart-panel"><div className="section-heading"><div><p className="overline">12-WEEK MOVEMENT</p><h2>关注度变化</h2></div><Link to="/problems">打开趋势矩阵 <ArrowUpRight size={15}/></Link></div><TrendChart series={top.map(x=>({name:x.name,color:x.color,values:x.history}))}/><div className="chart-legend">{top.map(x=><span key={x.id}><i style={{background:x.color}}/>{x.name}</span>)}</div></div><div className="market-split"><p className="overline">OPPORTUNITY MAP</p><h2>机会正在流向哪里</h2><div className="split-visual"><div className="split-number"><strong>68%</strong><span>传统行业 AI 辅助</span></div><div className="split-bar"><i/><b/></div><div className="split-number right"><strong>32%</strong><span>AI Native 产品</span></div></div><p>演示样本中，制造、金融与企业服务更强调流程集成；开发者工具和消费应用更偏向 AI Native。</p></div></section><HomeSignals signals={s.data.slice(0,3)}/></motion.div>}

function HomeSignals({signals}:{signals:Signal[]}){return <section className="lower-grid"><div className="feed-panel"><div className="section-heading"><div><p className="overline">LATEST SIGNALS</p><h2>最新求职快讯</h2></div><Link to="/signals">全部快讯 <ArrowUpRight size={15}/></Link></div><div className="signal-feed">{signals.map((item,i)=><SignalRow key={item.id} signal={item} index={i}/>)}</div></div><aside className="action-panel"><div className="action-icon"><Sparkles size={18}/></div><p className="overline">THIS WEEK'S MOVE</p><h2>把作品集从“功能展示”升级为“可靠性证明”。</h2><p>选择一个包含真实失败路径的 Agent 场景，记录成功率、恢复率、单次成功成本和人工接管比例。</p><div className="action-steps"><span><b>01</b>建立 30 条任务基线</span><span><b>02</b>注入超时与重复执行</span><span><b>03</b>输出失败归因报告</span></div><Link className="secondary-action" to="/problems/agent-evals">查看项目建议 <ArrowUpRight size={16}/></Link></aside></section>}
function SignalRow({signal,index}:{signal:Signal;index:number}){return <article><div className="feed-order">{String(index+1).padStart(2,"0")}</div><div><div className="feed-tags"><span>{signal.type}</span><small>{signal.relativeTime}</small></div><h3>{signal.title}</h3><p>{signal.source}</p><Link className="affected" to={`/problems/${signal.problemId}`}><Target size={14}/>查看关联问题</Link></div><strong className="impact">+{signal.impact}</strong></article>}

function PageIntro({eyebrow,title,description,aside}:{eyebrow:string;title:string;description:string;aside?:ReactNode}){return <div className="page-intro"><div><p className="overline">{eyebrow}</p><h1>{title}</h1><p>{description}</p></div>{aside}</div>}

function ProblemsPage(){const [params,setParams]=useSearchParams();const q=params.get("q")??"";const state=(params.get("state")??"") as TrendState|"";const industry=params.get("industry")??"";const [view,setView]=useState<"list"|"matrix">("list");const result=useLoad(()=>radarRepository.getProblems({q,state,industry}),[q,state,industry]);const all=useLoad(()=>radarRepository.getProblems(),[]);const set=(key:string,value:string)=>{const next=new URLSearchParams(params);value?next.set(key,value):next.delete(key);setParams(next)};const industries=[...new Set((all.data??[]).flatMap(p=>p.industries))];return <div className="page-wrap"><PageIntro eyebrow="DYNAMIC PROBLEM RADAR" title="动态难题" description="问题由证据聚类产生，会随新增数据升温、降温或退出视野。五类种子不构成固定栏目。" aside={<div className="view-switch"><button className={view==="list"?"active":""} onClick={()=>setView("list")}><List/>列表</button><button className={view==="matrix"?"active":""} onClick={()=>setView("matrix")}><LayoutGrid/>矩阵</button></div>}/><div className="filter-bar"><label className="search-field"><Search/><input value={q} onChange={e=>set("q",e.target.value)} placeholder="搜索问题、技能或岗位"/></label><label><span>趋势状态</span><select value={state} onChange={e=>set("state",e.target.value)}><option value="">全部状态</option><option value="new">新出现</option><option value="rising">升温</option><option value="steady">持续</option><option value="falling">降温</option></select></label><label><span>行业</span><select value={industry} onChange={e=>set("industry",e.target.value)}><option value="">全部行业</option>{industries.map(x=><option key={x}>{x}</option>)}</select></label><button className="clear-filter" onClick={()=>setParams({})}>清空</button></div>{result.loading?<LoadingBlock/>:result.error?<ErrorBlock/>:!result.data?.length?<div className="empty-state"><FileSearch/><h2>没有符合条件的问题</h2><p>尝试清空筛选条件，或扩大观察范围。</p></div>:view==="list"?<div className="problems-table"><div className="problem-table-head"><span>方向</span><span>趋势</span><span>相关岗位</span><span>置信</span></div>{result.data.map(p=><ProblemListItem key={p.id} problem={p}/>)}</div>:<ProblemMatrix problems={result.data}/>}</div>}
function ProblemListItem({problem}:{problem:Problem}){return <Link className="problem-list-item" to={`/problems/${problem.id}`}><span className="list-name"><i style={{background:problem.color}}/><span><strong>{problem.name}</strong><small>{problem.definition}</small></span></span><span className="list-trend"><Sparkline problem={problem}/><b>{problem.score}</b><TrendBadge problem={problem}/></span><span className="role-list">{problem.roles.slice(0,2).map(x=><em key={x}>{x}</em>)}</span><span className={`confidence ${problem.confidence}`}>{confidenceLabel[problem.confidence]}<ChevronRight/></span></Link>}
function ProblemMatrix({problems}:{problems:Problem[]}){return <div className="matrix-panel"><div className="matrix-y">证据置信度 →</div><div className="matrix-grid"><span className="axis-label top">高置信 / 快速升温</span><span className="axis-label bottom">待观察</span>{problems.map((p,i)=><Link to={`/problems/${p.id}`} className="matrix-dot" key={p.id} style={{left:`${Math.max(7,Math.min(91,38+p.delta*2.7))}%`,bottom:`${Math.max(8,Math.min(85,p.score-8))}%`,width:34+p.publishers*4,height:34+p.publishers*4,background:`${p.color}22`,borderColor:p.color,zIndex:20-i}}><span style={{background:p.color}}/><b>{p.name}</b><small>{p.score} · {stateLabel[p.state]}</small></Link>)}</div><div className="matrix-x">证据增长速度 →</div></div>}

function ProblemDetailPage(){const {id=""}=useParams();const navigate=useNavigate();const p=useLoad(()=>radarRepository.getProblem(id),[id]);const e=useLoad(()=>radarRepository.getEvidence({problemId:id}),[id]);const [selected,setSelected]=useState<Evidence>();const related=useLoad(()=>radarRepository.getProblems(),[]);if(p.loading||e.loading)return <LoadingBlock/>;if(p.error||e.error)return <ErrorBlock/>;if(!p.data)return <Navigate to="/problems" replace/>;const problem=p.data;return <div className="detail-page"><button className="back-link" onClick={()=>navigate(-1)}><ArrowLeft/>返回动态难题</button><div className="detail-hero"><div><div className="detail-badges"><TrendBadge problem={problem}/><span className={`confidence ${problem.confidence}`}>{confidenceLabel[problem.confidence]}</span></div><h1>{problem.name}</h1><p>{problem.definition}</p><div className="tag-row">{problem.aliases.map(x=><span key={x}>{x}</span>)}</div></div><div className="hero-score"><small>趋势得分</small><strong>{problem.score}</strong><span>/100</span></div></div><div className="detail-layout"><div className="detail-primary"><section className="detail-section"><div className="section-heading"><div><p className="overline">WHY IT MATTERS NOW</p><h2>为什么现在值得关注</h2></div><span className="date-range">{formatDate(problem.firstSeenAt)} — {formatDate(problem.lastSeenAt)}</span></div><blockquote>{problem.judgement}</blockquote><p className="body-copy">{problem.whyNow}</p></section><section className="detail-section"><div className="section-heading"><div><p className="overline">12-WEEK TREND</p><h2>证据变化</h2></div><span className="sample-note">4 条有效 / 5 条采集</span></div><TrendChart series={[{name:problem.name,color:problem.color,values:problem.history}]} height={300}/><p className="chart-caption">趋势得分由独立发布者、来源多样性、时间新鲜度和证据变化共同组成，不表示市场份额。</p></section><section className="detail-section"><div className="section-heading"><div><p className="overline">EVIDENCE LEDGER</p><h2>形成判断的证据</h2></div><Link to={`/evidence?problem=${problem.id}`}>打开证据库 <ArrowUpRight/></Link></div><div className="evidence-preview">{e.data?.map(item=><button key={item.id} onClick={()=>setSelected(item)}><span className={`status-dot ${item.status}`}/><span><small>{item.id} · {item.type} · {item.publisher}</small><strong>{item.title}</strong><em>{evidenceLabel[item.status]}</em></span><ChevronRight/></button>)}</div></section></div><aside className="detail-aside"><div className="detail-card"><p className="overline">MARKET FIT</p><h3>关联岗位</h3><div className="chip-cloud">{problem.roles.map(x=><span key={x}>{x}</span>)}</div><h3>能力关键词</h3><div className="chip-cloud skills">{problem.skills.map(x=><span key={x}>{x}</span>)}</div><h3>出现行业</h3><div className="chip-cloud muted">{problem.industries.map(x=><span key={x}>{x}</span>)}</div></div><div className="portfolio-card"><Sparkles/><p className="overline">PORTFOLIO PROJECT</p><h2>{problem.project}</h2><p>{problem.projectBrief}</p><div className="metric-list">{problem.metrics.map(x=><span key={x}><Check/>{x}</span>)}</div><div className="next-list">{problem.nextSteps.map((x,i)=><span key={x}><b>0{i+1}</b>{x}</span>)}</div></div>{related.data&&<div className="related-card"><h3>继续探索</h3>{related.data.filter(x=>x.id!==problem.id&&x.industries.some(i=>problem.industries.includes(i))).slice(0,3).map(x=><Link key={x.id} to={`/problems/${x.id}`}><i style={{background:x.color}}/><span>{x.name}<small>{stateLabel[x.state]} · {x.score}</small></span><ChevronRight/></Link>)}</div>}</aside></div><EvidenceDrawer evidence={selected} onClose={()=>setSelected(undefined)}/></div>}

function EvidenceDrawer({evidence,onClose}:{evidence?:Evidence;onClose:()=>void}){useEffect(()=>{if(!evidence)return;const previous=document.activeElement as HTMLElement|null;const handleKey=(event:KeyboardEvent)=>{if(event.key==="Escape")onClose()};document.addEventListener("keydown",handleKey);requestAnimationFrame(()=>document.querySelector<HTMLElement>(".drawer-close")?.focus());return()=>{document.removeEventListener("keydown",handleKey);previous?.focus()}},[evidence,onClose]);return <AnimatePresence>{evidence&&<><motion.button className="drawer-backdrop" aria-label="关闭证据详情" onClick={onClose} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}/><motion.aside className="evidence-drawer" role="dialog" aria-modal="true" aria-label="证据详情" initial={{x:"100%"}} animate={{x:0}} exit={{x:"100%"}} transition={{duration:.28,ease:[.2,.8,.2,1]}}><button className="drawer-close" onClick={onClose}><X/>关闭</button><p className="overline">{evidence.id} · SOURCE EVIDENCE</p><h2>{evidence.title}</h2><div className="drawer-meta"><span>{evidence.publisher}</span><span>{evidence.type}</span><span>{evidence.region}</span><span>{evidence.date}</span></div><div className={`verification-box ${evidence.status}`}><ShieldCheck/><div><strong>{evidenceLabel[evidence.status]}</strong><p>{evidence.status==="verified"?"正文已完成内容校验，可以参与趋势计算。":"该页面只保留为线索，不参与趋势统计。"}</p></div></div><h3>证据片段</h3><blockquote>{evidence.excerpt}</blockquote><h3>提取技能</h3><div className="chip-cloud">{evidence.skills.map(x=><span key={x}>{x}</span>)}</div><div className="drawer-warning">这是用于验证产品交互的模拟来源，不代表真实报道。</div><a className="primary-action drawer-source" href={evidence.url} target="_blank" rel="noopener noreferrer">打开模拟原文 <ArrowUpRight/></a></motion.aside></>}</AnimatePresence>}

function SignalsPage(){const [type,setType]=useState<SourceType|"">("");const data=useLoad(()=>radarRepository.getSignals({type}),[type]);return <div className="page-wrap"><PageIntro eyebrow="CAREER BRIEFING" title="求职快讯" description="把招聘、生产复盘、研究和产业报告压缩成对程序员有用的变化信号。" aside={<div className="page-stat"><strong>{data.data?.length??"—"}</strong><span>当前筛选信号</span></div>}/><div className="tabs">{(["","招聘","生产实践","行业报告","评测研究","政策"] as Array<SourceType|"">).map(x=><button key={x||"all"} className={type===x?"active":""} onClick={()=>setType(x)}>{x||"全部"}</button>)}</div>{data.loading?<LoadingBlock/>:data.error?<ErrorBlock/>:!data.data?.length?<div className="empty-state"><FileSearch/><h2>当前筛选下没有新信号</h2><p>切换来源类型，或等待下一批证据更新。</p></div>:<div className="timeline">{data.data.map((signal,i)=><article key={signal.id}><div className="timeline-mark"><span/><i/></div><div className="timeline-date">{formatDate(signal.date)}<small>{signal.relativeTime}</small></div><div className="timeline-content"><div><span className="source-type">{signal.type}</span><span className="impact-badge">趋势影响 +{signal.impact}</span></div><h2>{signal.title}</h2><p>{signal.summary}</p><div className="timeline-foot"><span>{signal.source}</span><Link to={`/problems/${signal.problemId}`}>查看关联难题 <ArrowUpRight/></Link></div></div></article>)}</div>}</div>}

function EvidencePage(){const [params,setParams]=useSearchParams();const q=params.get("q")??"";const type=(params.get("type")??"") as SourceType|"";const status=(params.get("status")??"") as Evidence["status"]|"";const problemId=params.get("problem")??"";const [selected,setSelected]=useState<Evidence>();const data=useLoad(()=>radarRepository.getEvidence({q,type,status,problemId}),[q,type,status,problemId]);const set=(key:string,value:string)=>{const next=new URLSearchParams(params);value?next.set(key,value):next.delete(key);setParams(next)};return <div className="page-wrap"><PageIntro eyebrow="EVIDENCE LEDGER" title="证据库" description="每一个趋势判断都能回到来源。验证状态、权威等级和模拟数据边界在这里公开。" aside={<div className="page-stat"><strong>{data.data?.length??"—"}</strong><span>当前筛选结果</span></div>}/><div className="filter-bar evidence-filters"><label className="search-field"><Search/><input value={q} onChange={e=>set("q",e.target.value)} placeholder="搜索标题、发布方或技能"/></label><label><span>来源类型</span><select value={type} onChange={e=>set("type",e.target.value)}><option value="">全部类型</option><option>招聘</option><option>生产实践</option><option>行业报告</option><option>评测研究</option><option>政策</option></select></label><label><span>验证状态</span><select value={status} onChange={e=>set("status",e.target.value)}><option value="">全部状态</option><option value="verified">内容已验证</option><option value="lead_only">仅作线索</option><option value="failed">访问失败</option></select></label><button className="clear-filter" onClick={()=>setParams({})}>清空</button></div>{data.loading?<LoadingBlock/>:data.error?<ErrorBlock/>:!data.data?.length?<div className="empty-state"><FileSearch/><h2>没有符合条件的证据</h2><p>尝试清空筛选条件，或查看仅作线索的来源。</p></div>:<div className="evidence-table-wrap"><table className="evidence-table"><thead><tr><th>状态</th><th>来源与日期</th><th>支持的判断</th><th>技能</th><th/></tr></thead><tbody>{data.data.map(item=><tr key={item.id} tabIndex={0} onClick={()=>setSelected(item)} onKeyDown={event=>{if(event.key==="Enter"||event.key===" ")setSelected(item)}}><td><span className={`evidence-status ${item.status}`}><i/>{evidenceLabel[item.status]}</span><small className="authority">权威等级 {item.authority}</small></td><td><strong>{item.publisher}</strong><small>{item.type} · {item.region} · {item.date}</small></td><td><strong>{item.title}</strong><p>{item.excerpt}</p></td><td><div className="table-skills">{item.skills.map(x=><span key={x}>{x}</span>)}</div></td><td><ChevronRight/></td></tr>)}</tbody></table></div>}<EvidenceDrawer evidence={selected} onClose={()=>setSelected(undefined)}/></div>}

function MethodPage(){const steps=[{icon:<Database/>,index:"01",title:"采集与验证",text:"保存来源、抓取状态、时间、内容哈希与短证据片段。"},{icon:<FileSearch/>,index:"02",title:"事实抽取",text:"抽取明确问题、岗位、技能、行业和可量化数据。"},{icon:<LayoutGrid/>,index:"03",title:"动态归并",text:"把语义接近的问题聚类，保留别名、变化和人工复核入口。"},{icon:<TrendingUp/>,index:"04",title:"趋势评分",text:"综合发布方、来源多样性、新鲜度与窗口变化，不按文章数堆分。"},{icon:<Sparkles/>,index:"05",title:"行动建议",text:"分开呈现观察事实、系统推断和程序员可以执行的下一步。"}];return <div className="page-wrap method-page"><PageIntro eyebrow="RESEARCH PROTOCOL" title="数据方法" description="透明不是附录，而是产品功能。每项判断都公开它来自哪里、如何形成、有哪些边界。"/><div className="method-flow">{steps.map((step,i)=><article key={step.index}><div className="method-icon">{step.icon}</div><span>{step.index}</span><h2>{step.title}</h2><p>{step.text}</p>{i<steps.length-1&&<ChevronRight className="flow-arrow"/>}</article>)}</div><div className="method-grid"><section><p className="overline">SCORING MODEL</p><h2>趋势得分不是市场份额</h2><div className="score-formula"><span><b>30%</b>独立发布方</span><span><b>25%</b>生产与招聘交叉</span><span><b>20%</b>来源类型多样性</span><span><b>15%</b>时间新鲜度</span><span><b>10%</b>窗口变化</span></div><p>单一发布者集中发文会被降权；抓取失败或只有标题的页面贡献为零。</p></section><section className="boundary-card"><p className="overline">MVP BOUNDARY</p><h2>当前是交互验证，不是真实结论</h2><ul><li><Check/>所有页面使用 50 条结构化模拟证据</li><li><Check/>40 条标记为可验证样本，10 条作为线索或失败</li><li><Check/>问题可以新增、升温、降温与退出</li><li><Check/>真实数据接入后，页面组件无需重写</li></ul></section></div><div className="fact-inference"><div><span>FACT</span><h3>事实</h3><p>来源明确写出的岗位要求、统计数据或工程问题。</p></div><ChevronRight/><div><span>INFERENCE</span><h3>推断</h3><p>多个独立来源共同支持的趋势判断，并显示置信度。</p></div><ChevronRight/><div><span>ACTION</span><h3>建议</h3><p>结合岗位与技术难题，给程序员的学习和作品集方向。</p></div></div></div>}

export default function App(){return <Shell><AnimatePresence mode="wait"><Routes><Route path="/" element={<HomePage/>}/><Route path="/problems" element={<ProblemsPage/>}/><Route path="/problems/:id" element={<ProblemDetailPage/>}/><Route path="/signals" element={<SignalsPage/>}/><Route path="/evidence" element={<EvidencePage/>}/><Route path="/method" element={<MethodPage/>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes></AnimatePresence></Shell>}
